import {freshState,id,validateState} from './core.js';
export const locations=s=>[s.wall,...(s.otherWalls||[])];
export function selectLocation(s,key){const next=locations(s).find(w=>w.id===key);if(!next)throw Error('Local não encontrado.');if(next.id===s.wall.id)return;s.otherWalls=locations(s).filter(w=>w.id!==key);s.wall=next;}
export function addLocation(s,name){if(!name?.trim())throw Error('Informe o nome do local.');if(locations(s).length>=30)throw Error('Limite de 30 locais.');const wall=freshState().wall;wall.name=name.trim().slice(0,80);s.otherWalls=[...(s.otherWalls||[]),s.wall];s.wall=wall;return wall;}
export function exportBoulder(route){const copy=structuredClone(route),faceIds=new Set(copy.snapshot.holds.filter(h=>copy.assignments[h.id]?.length).map(h=>h.faceId));copy.snapshot.faces=copy.snapshot.faces.filter(f=>faceIds.has(f.id));copy.snapshot.holds=copy.snapshot.holds.filter(h=>faceIds.has(h.faceId));return {format:'homeclimb-boulder',version:1,route:copy};}
export function readBoulder(payload){if(payload?.format!=='homeclimb-boulder'||payload.version!==1||!payload.route)throw Error('Escolha um arquivo de boulder compartilhado do HomeClimb.');const route=structuredClone(payload.route);validateState({version:1,wall:route.snapshot,routes:[route],attempts:[]});return route;}
export function importBoulder(s,payload){const route=readBoulder(payload);if(s.routes.length>=1000)throw Error('Limite de boulders atingido.');const exists=locations(s).some(w=>w.id===route.snapshot.id);if(!exists&&locations(s).length>=30)throw Error('Limite de locais atingido.');if(s.routes.some(r=>r.id===route.id))route.id=id();if(!exists)s.otherWalls=[...(s.otherWalls||[]),structuredClone(route.snapshot)];s.routes.push(route);return route;}
